ew UnityEngine.InputSystem.LowLevel.KeyboardState());yield return null;}if(humans==1||humans==4){var capture=Type.GetType("LWS.TruckSports.SportsControlledCapture, Assembly-CSharp",true).GetMethods().First(method=>method.Name=="Save"&&method.GetParameters()[0].ParameterType.Name=="SportsEventSession");foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)})capture.Invoke(null,new object[]{match,size.x,size.y,"Logs/TruckSports/EssentialRelease/Parking/cab-"+humans+"-"+size.x+"x"+size.y+".png",null});}options.GetMethod("Set").Invoke(null,new object[]{true});Call(view,"Select",1);yield return null;Assert.That(((Array)Get(match,"cameras")).Length,Is.EqualTo(4));options.GetMethod("Set").Invoke(null,new object[]{false});Call(view,"Select",0);yield return null;Assert.That(((Array)Get(match,"cameras")).Length,Is.EqualTo(1));Assert.That(((Camera)((Array)Get(match,"cameras")).GetValue(0)).orthographic,Is.True);Call(match,"SetupScreen");}Call(match,"AllBots");Call(view,"Select",2);Assert.That(StartChecked());yield return null;Assert.That((bool)Get(view,"NeedsArena"),Is.True);Assert.That(((Camera)((Array)Get(match,"cameras")).GetValue(0)).enabled,Is.True,"AI-only with hidden AI views needs a live broadcast camera.");}
