 IEnumerator TrailerDrop(Vector3 position){
  yield return Load("TruckTrailerPlug","TrailerPlugMatch");keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);
  var setup=Get(match,"setup");Set(setup,"count",1);var player=((Array)Get(setup,"players")).GetValue(0);
  var source=player.GetType().GetField("source");source.SetValue(player,Enum.Parse(source.FieldType,"Keyboard"));
  Assert.That(StartChecked());Time.timeScale=3;float deadline=Time.realtimeSinceStartup+8;
  while(Get(match,"Phase").ToString()!="Swing"&&Time.realtimeSinceStartup<deadline)yield return null;
  Assert.That(Get(match,"Phase").ToString(),Is.EqualTo("Swing"));
  // This fixture isolates real trailer/rim support and seal scoring. Crowd
  // collision/evasion is exercised by the separate full native match probe.
  Set(match,"nextSpawn",float.MaxValue);
  foreach(var pedestrian in (System.Collections.IEnumerable)Get(match,"Crowd"))((Component)pedestrian).gameObject.SetActive(false);
  var rig=Get(match,"rig");var body=(Rigidbody)Get(rig,"trailer");body.linearVelocity=new Vector3(2,-3,1);body.angularVelocity=new Vector3(.1f,.4f,.2f);
  var velocity=body.linearVelocity;var angular=body.angularVelocity;Assert.That((bool)Call(match,"Release"));
  Assert.That(body.linearVelocity,Is.EqualTo(velocity));Assert.That(body.angularVelocity,Is.EqualTo(angular));Assert.That((bool)Call(match,"Release"),Is.False);
  yield return null;
  // Explicit physical fixture: place the detached real trailer for a vertical drop.
  // This does not represent a naturally earned human or AI delivery.
  body.position=position;body.rotation=Quaternion.identity;body.linearVelocity=body.angularVelocity=Vector3.zero;body.WakeUp();Physics.SyncTransforms();
  deadline=Time.realtimeSinceStartup+12;while(Get(match,"Phase").ToString()!="AttemptResult"&&Time.realtimeSinceStartup<deadline)yield return null;
  Assert.That(Get(match,"Phase").ToString(),Is.EqualTo("AttemptResult"));
 }
