 [UnityTest]public IEnumerator ReplayCloneRetainsSkinBonesWithoutDuplicatingPhysics(){
  var source=new GameObject("Authored skinned replay fixture");var body=source.AddComponent<Rigidbody>();body.useGravity=false;source.AddComponent<BoxCollider>();
  var bone=new GameObject("Authored skeleton bone").transform;bone.SetParent(source.transform,false);
  var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-.5f,0,0),new Vector3(.5f,0,0),new Vector3(0,1,0)};mesh.triangles=new[]{0,1,2};mesh.RecalculateNormals();mesh.bindposes=new[]{Matrix4x4.identity};mesh.boneWeights=new[]{new BoneWeight{boneIndex0=0,weight0=1},new BoneWeight{boneIndex0=0,weight0=1},new BoneWeight{boneIndex0=0,weight0=1}};
  var skin=source.AddComponent<SkinnedMeshRenderer>();skin.sharedMesh=mesh;skin.bones=new[]{bone};skin.rootBone=bone;skin.localBounds=new Bounds(Vector3.up*.5f,Vector3.one*2);
  var copy=Type.GetType("LWS.TruckSports.SportsReplayVisuals, Assembly-CSharp",true).GetMethod("Copy");
  var clone=(GameObject)copy.Invoke(null,new object[]{source.transform});var ghost=clone.GetComponent<SkinnedMeshRenderer>();
  Assert.That(ghost,Is.Not.Null);Assert.That(ghost.sharedMesh,Is.SameAs(mesh));Assert.That(ghost.bones[0],Is.Not.SameAs(bone));Assert.That(ghost.bones[0].IsChildOf(clone.transform));Assert.That(ghost.rootBone,Is.SameAs(ghost.bones[0]));
  Assert.That(clone.GetComponentsInChildren<Rigidbody>(true).Length,Is.Zero);Assert.That(clone.GetComponentsInChildren<Collider>(true).Length,Is.Zero);Assert.That(clone.GetComponentsInChildren<MonoBehaviour>(true).Length,Is.Zero);
  UnityEngine.Object.Destroy(source);UnityEngine.Object.Destroy(clone);UnityEngine.Object.Destroy(mesh);yield return null;
 }

